EXTRA = [{'id': 'EG-29', 'title': 'Lift im Detail: Kabine, Tür und Schacht', 'topic': 'Lift-Detail', 'roi': [3810, 1635, 3950, 1830], 'base': 'clean', 'rules': ['R05', 'R14', 'R23'], 'sections': [['Woran erkennt man den Lift?', 'Im schraffierten Schacht liegt ein eigener rechteckiger Kabinenumriss. Im Inneren stehen FWA, 110 × 210 cm und 13 Pers. / 1000 kg. Kabine, Türmechanik und der DXF-Layer „Neubau_430 Aufzug“ stützen die Zuordnung gemeinsam.'], ['Welche Linie zeigt welchen Teil?', 'Violett folgt dem Kabinenumriss. Rot liegt auf der massiven Schachteinfassung. Blau hebt die parallelen Schiebetürlinien an der oberen Kabinenseite hervor. Orange zeigt den technischen Zwischenraum seitlich der Kabine.'], ['Wie entsteht hier eine Verbindung?', 'Vom Vorbereich führt der Zugang an der Türseite in die Kabine, wenn diese auf dem Geschoss hält und die Türen geöffnet sind. Die Fahrt zum anderen Geschoss ist eine eigene Verbindung. Der technische Zwischenraum ist kein Fußweg; eine Zielhöhe ist hier nicht bestätigt.']], 'image': 'bilder/EG-29.png', 'annotation_count': 6, 'markers': [], 'source_pdf': 'quellen/Schule_SH22_EG.pdf', 'source_dxf': 'quellen/20220225-SH22-LKS-GE-AP-EG-01-C.dxf', 'pdf_page': 1, 'roi_unit': 'PDF_point_top_left_origin', 'geometry_type': 'Suchbereich_keine_Objektgrenze', 'status': 'am_Originalplan_visuell_interpretiert_kein_Engine_Test', 'cad_bbox_mm': [7253.499877448738, 19385.114773933517, 9722.98519301915, 22824.755034906593]}, {'id': 'EG-27', 'title': 'Mauer lesen: zwei Kanten und Material dazwischen', 'topic': 'Mauer-Detail', 'roi': [1460, 930, 1540, 1020], 'base': 'clean', 'sections': [['Was genau ist die Mauer?', 'Der geschlossene rote Rahmen umfasst das gesamte Wandstück. Im Rahmen begrenzen die blaue und orange Randlinie ein schraffiertes Band. Material zwischen zwei Kanten und die Fortsetzung nach oben und unten sind gemeinsam die Belege für einen Wandkörper.'], ['Warum kein Durchgang?', 'Zwischen den Kanten liegt Material. Der Körper kann diese Fläche nicht queren. Ein heller Zwischenraum in einer mehrschichtigen Darstellung ist ohne Öffnungsbeleg kein Gang.'], ['Welche Linie gehört nicht dazu?', 'Die Beschriftung im Raum und ihre Buchstaben bilden keine Geometriegrenze. Wanddicke nur am Original-DXF oder an einer belegten Maßangabe bestimmen.']], 'rules': ['R01', 'R02'], 'image': 'bilder/EG-27.png', 'annotation_count': 3, 'markers': [], 'source_pdf': 'quellen/Schule_SH22_EG.pdf', 'source_dxf': 'quellen/20220225-SH22-LKS-GE-AP-EG-01-C.dxf', 'pdf_page': 1, 'roi_unit': 'PDF_point_top_left_origin', 'geometry_type': 'Suchbereich_keine_Objektgrenze', 'status': 'am_Originalplan_visuell_interpretiert_kein_Engine_Test', 'cad_bbox_mm': [-34198.575062483185, 33672.85124259091, -32787.440596442946, 35260.37751688617]}, {'id': 'EG-28', 'title': 'Außenwand: Kern, Dämmung und Eckanschluss', 'topic': 'Mauer-Detail', 'roi': [4965, 2710, 5110, 2840], 'base': 'clean', 'sections': [['Gesamten Aufbau erkennen', 'Der schraffierte Kern und die mit Schlaufen dargestellte Dämmlage gehören zum festen Außenabschluss. Die farbigen Konturen umfassen den gesamten sichtbaren Wandaufbau.'], ['Warum ist die Ecke wichtig?', 'Die Schichten setzen sich um die Ecke fort. Innenkante und Außenkante bilden zusammen eine geschlossene Begrenzung. Der Innenraum endet vor diesem Aufbau.'], ['Für die Raumerkennung', 'Die Außenseite des Kerns allein ist keine ausreichende Hindernisgrenze. Auch breite Dämm- und Bekleidungsschichten nicht als begehbaren Streifen ausgeben.']], 'rules': ['R01', 'R02'], 'image': 'bilder/EG-28.png', 'annotation_count': 4, 'markers': [], 'source_pdf': 'quellen/Schule_SH22_EG.pdf', 'source_dxf': 'quellen/20220225-SH22-LKS-GE-AP-EG-01-C.dxf', 'pdf_page': 1, 'roi_unit': 'PDF_point_top_left_origin', 'geometry_type': 'Suchbereich_keine_Objektgrenze', 'status': 'am_Originalplan_visuell_interpretiert_kein_Engine_Test', 'cad_bbox_mm': [27626.75373090464, 1569.542140175544, 30184.434950602565, 3862.635647490927]}]
